def log_status(message: str):
    """Prints status updates to stderr to avoid corrupting the stdout byte stream."""
    sys.stderr.write(f"[STATUS] {message}\n")
    sys.stderr.flush()


def check_cache_status():
    """Checks HuggingFace cache directory and reports status."""
    import os
    hf_home = os.environ.get('HF_HOME', os.path.expanduser('~/.cache/huggingface'))
    cache_path = os.path.join(hf_home, 'hub')

    if os.path.exists(cache_path):
        cache_size_bytes = sum(
            os.path.getsize(os.path.join(dirpath, filename))
            for dirpath, dirnames, filenames in os.walk(cache_path)
            for filename in filenames
        )
        cache_size_gb = cache_size_bytes / (1024**3)
        log_status(f"Model cache location: {cache_path} ({cache_size_gb:.2f} GB)")
    else:
        log_status(f"Model cache directory does not exist yet: {cache_path}")
